package com.example.parcel.application.parcel;

import static org.junit.jupiter.api.Assertions.*;

import com.example.parcel.domain.parcel.*;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;

class RegisterParcelTest {
    private final List<Parcel> saved = new ArrayList<>();
    private final RegisterParcel registerParcel = new RegisterParcel(saved::add);

    @Test
    void savesRegisteredParcel() {
        registerParcel.execute(new ParcelId("p-1"), 12);
        assertEquals(1, saved.size());
    }

    @Test
    void savesNothingWhenTooHeavy() {
        assertThrows(ParcelTooHeavyException.class, () -> registerParcel.execute(new ParcelId("p-1"), 31));
        assertTrue(saved.isEmpty());
    }
}
