package com.example.parcel.infrastructure.parcel;

import com.example.parcel.domain.parcel.Parcel;
import com.example.parcel.domain.parcel.ParcelId;
import com.example.parcel.domain.parcel.ParcelRepository;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public final class InMemoryParcelRepository implements ParcelRepository {
    private final Map<ParcelId, Parcel> parcels = new ConcurrentHashMap<>();

    @Override
    public void save(Parcel parcel) {
        parcels.put(parcel.id(), parcel);
    }
}
