package com.example.parcel.app.parcel;

import com.example.parcel.application.parcel.RegisterParcel;
import com.example.parcel.domain.parcel.ParcelRepository;
import com.example.parcel.infrastructure.parcel.InMemoryParcelRepository;
import jakarta.enterprise.inject.Produces;
import jakarta.inject.Singleton;

public class ParcelWiring {
    @Produces
    @Singleton
    ParcelRepository parcelRepository() {
        return new InMemoryParcelRepository();
    }

    @Produces
    @Singleton
    RegisterParcel registerParcel(ParcelRepository parcels) {
        return new RegisterParcel(parcels);
    }
}
