package com.example.parcel.app.parcel;

import com.example.parcel.application.parcel.RegisterParcel;
import com.example.parcel.domain.parcel.ParcelId;
import com.example.parcel.domain.parcel.ParcelTooHeavyException;
import jakarta.inject.Inject;
import jakarta.ws.rs.Consumes;
import jakarta.ws.rs.POST;
import jakarta.ws.rs.Path;
import jakarta.ws.rs.core.MediaType;
import jakarta.ws.rs.core.Response;
import jakarta.ws.rs.ext.ExceptionMapper;
import jakarta.ws.rs.ext.Provider;

@Path("/parcels")
public class ParcelResource {
    public record RegisterParcelRequest(String parcelId, double weightKg) {}

    @Inject
    RegisterParcel registerParcel;

    @POST
    @Consumes(MediaType.APPLICATION_JSON)
    public Response register(RegisterParcelRequest request) {
        if (request == null) {
            throw new IllegalArgumentException("body is required");
        }
        registerParcel.execute(new ParcelId(request.parcelId()), request.weightKg());
        return Response.status(Response.Status.CREATED).build();
    }

    @Provider
    public static class TooHeavy implements ExceptionMapper<ParcelTooHeavyException> {
        @Override
        public Response toResponse(ParcelTooHeavyException e) {
            return Response.status(422).type(MediaType.TEXT_PLAIN).entity(e.getMessage()).build();
        }
    }

    @Provider
    public static class BadRequest implements ExceptionMapper<IllegalArgumentException> {
        @Override
        public Response toResponse(IllegalArgumentException e) {
            return Response.status(400).type(MediaType.TEXT_PLAIN).entity(e.getMessage()).build();
        }
    }
}
